from pydantic import BaseModel, Field

class CandidateSchema(BaseModel):
    primaNeta: str|None = Field(default=None, description="Analiza el documento completo y localiza la sección de montos de la póliza, típicamente presentada en un bloque tipo tabla con conceptos económicos (por ejemplo: “PRIMA NETA”, “PRIMA NETA TOTAL”, “Prima Neta”, etc.) y sus importes alineados a la derecha, usualmente en la parte media o final del documento, cercana a otros conceptos como IVA, Total, Derechos de Póliza, Financiamiento, etc.  Identifica el renglón cuyo encabezado o etiqueta contenga explícitamente el texto “PRIMA NETA” (ignora mayúsculas/minúsculas y acentos). Suele estar: - En una columna de texto a la izquierda (concepto) y el valor numérico a la derecha. - Junto o inmediatamente encima de la línea de IVA. - En la zona de “detalle de prima” o “resumen de prima” de la carátula de la póliza.  Una vez localizado el renglón de “PRIMA NETA”: - Extrae únicamente el número asociado a ese concepto. - Ignora el signo de moneda si aparece (por ejemplo, ‘$’ o ‘MXN’). - No consideres separadores de miles (comas, espacios); respeta solo el punto como separador decimal. - Si aparece más de un número en la misma línea, selecciona el que esté visualmente alineado como el importe (generalmente el más a la derecha o inmediatamente después de la etiqueta).  Devuelve el valor numérico extraído exactamente con el mismo formato de decimales que se muestra en el documento, pero sin comas de miles, solo con punto decimal.")
    primerPago: str|None = Field(default=None, description="Localiza en el documento la sección de forma de pago o resumen de pagos, que suele encontrarse cerca del cuadro de prima, en un bloque con textos como “PRIMER PAGO”, “PRIMER PAGO A REALIZAR”, “Pago inicial”, “Primer recibo”, o similar. Este bloque generalmente está: - En la parte media o inferior de la carátula, cerca del total de la póliza. - Presentado como una tabla o lista de conceptos de pago: primer pago, pagos posteriores, número de pagos, etc.  Busca una línea cuyo encabezado contenga explícitamente “PRIMER PAGO” (sin distinguir mayúsculas, minúsculas o acentos). Puede venir acompañado de descripciones como “a la firma”, “de contado”, “pago inicial”. El importe correspondiente suele estar: - A la derecha de la etiqueta en la misma fila, o - Debajo, pero claramente alineado a esa etiqueta.  Una vez encontrado el rótulo de “PRIMER PAGO”: - Extrae únicamente el importe asociado a ese concepto. - Ignora símbolos de moneda (‘$’, ‘MXN’, etc.) y cualquier texto adicional. - Elimina separadores de miles (comas o espacios) y conserva solo el punto como separador decimal. - Si existe una columna de totales y otra de subtotales, el “Primer Pago” suele ser un solo importe destacado; usa el que esté directamente en la fila de “PRIMER PAGO”.  Devuelve ese valor numérico con el mismo número de decimales mostrados en el documento, pero sin comas de miles.")
    pagoPosterior: str|None = Field(default=None, description="Busca el bloque donde se detalla el esquema de pagos, usualmente muy cercano al dato de “PRIMER PAGO”. Este bloque puede llamarse “Forma de pago”, “Plan de pagos”, “Calendario de pagos” o similar.  Dentro de esa sección, identifica el renglón etiquetado como “PAGOS POSTERIORES”, “PAGO POSTERIOR”, “Pagos subsecuentes”, “Pagos siguientes”, o variaciones equivalentes. Normalmente aparece: - En la misma tabla donde está el “Primer pago”. - En una fila inmediatamente debajo o después de “PRIMER PAGO”.  Una vez encontrado el encabezado de “PAGO(S) POSTERIOR(ES)”: - Localiza el importe que esté en la misma fila, alineado como valor numérico (generalmente a la derecha). - Ignora cualquier texto como “mensuales”, “c/u”, “por recibo”, etc. - No tomes en cuenta comas de miles; solo conserva el punto como separador decimal.  Si el documento indica explícitamente que los pagos posteriores son cero (por ejemplo “0.00”, “$0.00”, “N/A 0”), toma ese cero como valor.  Devuelve exclusivamente el número correspondiente al pago posterior, manteniendo el formato de decimales mostrado, pero sin separador de miles.")
    descuento: str|None = Field(default=None, description="Localiza la sección de desglose de la prima donde se listan conceptos como Prima Neta, Descuento, Recargos, IVA, Derechos, Total, etc. Esta sección suele estar en un bloque tipo tabla con dos columnas principales: concepto (izquierda) e importe (derecha), generalmente en la parte media o inferior del documento.  Dentro de este bloque, identifica la fila cuyo texto contenga la palabra “DESCUENTO” (por ejemplo “DESCUENTO”, “Descuento aplicado”, “Descuento comercial”). No consideres menciones de “descuento” en textos explicativos extensos; enfócate en la tabla de importes.  Una vez identificada la fila de “DESCUENTO”: - Extrae el importe asociado en la misma fila. - Si el descuento se muestra como número negativo (p.ej. “-1,000.00”), conserva el signo negativo en el número devuelto. - Ignora cualquier símbolo de moneda y elimina las comas de miles, respetando solo el punto decimal. - Si aparece “0.00” u otro valor de cero, toma ese valor tal cual.  Devuelve solo el número del descuento, con sus decimales tal y como aparezcan, pero sin comas de miles.")
    iva: str|None = Field(default=None, description="Ubica el bloque de desglose de importes de la póliza donde se muestran conceptos fiscales y de prima, como “PRIMA NETA”, “IVA”, “Total”, “Derechos de póliza”, etc. Este bloque casi siempre está organizado en forma de tabla o listado alineado, en la zona de totales de la póliza.  Dentro de ese bloque, busca específicamente la línea cuyo encabezado contenga “IVA” o “I.V.A.” (puede incluir aclaraciones como “IVA 16%”, “IVA sobre prima”, etc.). El valor de IVA se presentará: - A la derecha de la etiqueta en la misma fila, o - Inmediatamente debajo pero alineado a la columna de importes.  Al localizar la línea de IVA: - Extrae exclusivamente el importe numérico asociado a ese IVA. - Ignora signos de moneda y cualquier texto del tipo “16%”, “8%”, “Incluido”, etc. - Elimina separadores de miles (comas, espacios) y respeta solo el punto como separador decimal.  Devuelve el valor numérico correspondiente al IVA con el mismo número de decimales que se muestre, pero sin comas de miles.")
    tasaFinanciamiento: str|None = Field(default=None, description="En la misma sección donde se describe la forma de pago o condiciones financieras (cerca de “Primer Pago”, “Pagos posteriores” y el total), localiza cualquier referencia a tasas o cargos de financiamiento. Esta información suele aparecer como: - Una fila de concepto “FINANCIAMIENTO”, “CARGO POR FINANCIAMIENTO”, “TASA DE FINANCIAMIENTO”, o - Un texto tipo “Tasa de financiamiento: X%” asociado a la tabla de pagos.  Diferencia claramente entre: - El importe de financiamiento (un monto en dinero), y - La tasa de financiamiento (un porcentaje). Este campo requiere la tasa.  Una vez ubicado el texto con “Tasa de financiamiento” o equivalente: - Localiza el valor numérico asociado (generalmente un porcentaje como “0%”, “3.5%”, “10.00%”). - Extrae solo la parte numérica, ignorando el símbolo “%” y texto adicional. - Si la tasa se indica explícitamente como cero (0, 0.0, 0.00), toma ese cero. - No uses comas como separador de miles; si existieran, elimínalas y deja solo el punto decimal.  Devuelve únicamente el valor numérico de la tasa de financiamiento, expresado como número decimal (no porcentaje con %), conservando los decimales que aparezcan.")
    derechoPoliza: str|None = Field(default=None, description="Ubica el bloque de conceptos de cobro asociados a la emisión de la póliza donde se muestran rubros como “Derechos de póliza”, “Gastos de expedición”, “Derecho de emisión”, u otros cargos administrativos. Este bloque suele estar junto al desglose de Prima Neta, IVA y Total, en una tabla de conceptos (izquierda) vs importes (derecha).  Busca una fila cuyo texto contenga “DERECHO” y “PÓLIZA” (por ejemplo “DERECHO DE PÓLIZA”, “DERECHOS DE POLIZA”) o equivalentes como “GASTOS DE EXPEDICIÓN” si queda claro que es el cargo de emisión de la póliza.  Una vez encontrado el renglón correspondiente: - Extrae el importe monetario asociado a ese concepto en la misma fila. - Ignora símbolos de moneda y cualquier nota explicativa. - Elimina comas de miles y conserva solo el punto decimal.  Si el documento muestra explícitamente que no hay cargo por derecho de póliza (por ejemplo, “0.00”, “$0.00”, o la fila está en blanco), toma el valor numérico mostrado o, si no hay ningún número, interpreta como campo vacío.  Devuelve únicamente el valor numérico con sus decimales, sin comas de miles. Si el documento no muestra ningún número para este concepto, devuelve el campo vacío.")
    total: str|None = Field(default=None, description="Localiza el bloque de resumen de montos de la póliza donde aparecen los conceptos finales como Prima Neta, IVA, Derechos, Descuentos y un renglón destacado de “TOTAL”. Este total puede estar etiquetado como “TOTAL”, “TOTAL A PAGAR”, “IMPORTE TOTAL”, “TOTAL PÓLIZA” o similar.  Este renglón de total normalmente: - Está en la parte inferior del cuadro de importes. - Suele estar en negritas, mayúsculas o con algún resaltado. - El importe aparece alineado a la derecha y puede ser el mismo que el del “Primer Pago” cuando el esquema de pagos es de contado.  Una vez identificado el rótulo de “TOTAL” (o equivalente claro de importe total a pagar): - Extrae exclusivamente el número que representa el importe total. - Ignora símbolos de moneda y cualquier texto extra (por ejemplo “MXN”, “IVA incluido”, etc.). - Elimina las comas de miles y conserva solo el punto como separador decimal.  Si existieran varios totales parciales (por ejemplo “Total antes de impuestos”, “Total con impuestos”), selecciona el que represente el “total a pagar” final. Este suele ir acompañado de textos como “a pagar”, “con impuestos”, “Total póliza”.  Devuelve solo el valor numérico con los decimales que tenga en el documento, sin separadores de miles.")
